mapper.select:
SELECT

FROM jiankongyujing a
LEFT JOIN shangpin_order b ON a.shangpin_order_id = b.id
LEFT JOIN yonghu c ON a.yonghu_id = c.id


        and a.id in

            #{item}



        and a.jiankongyujing_uuid_number like CONCAT('%', #{params.jiankongyujingUuidNumber}, '%')


        and a.jiankongyujing_name like CONCAT('%', #{params.jiankongyujingName}, '%')


        and a.jiankong_types = #{params.jiankongTypes}


        and a.yujing_level_types = #{params.yujingLevelTypes}


        and a.yujing_status_types = #{params.yujingStatusTypes}


        and a.yujing_mode_types = #{params.yujingModeTypes}


        and a.yonghu_id = #{params.yonghuId}


        and a.shangpin_order_id = #{params.shangpinOrderId}


        and a.jiankong_object like CONCAT('%', #{params.jiankongObject}, '%')


        and a.jiankong_data like CONCAT('%', #{params.jiankongData}, '%')


        and a.yujing_threshold like CONCAT('%', #{params.yujingThreshold}, '%')


        and a.yujing_source like CONCAT('%', #{params.yujingSource}, '%')


order by a.${params.sort} ${params.order}
